goodExamples:
uint32_t next_index(uint32_t i)
{
    i = i + 1U;
    return i;
}

badExamples:
uint32_t next_index(uint32_t i)
{
    /* Unsequenced modification and use of i - undefined behavior. */
    return i++ + i;
}

goodExamples:
bool accumulate_torque(int32_t acc, int32_t delta, int32_t *out)
{
    if ((delta > 0) && (acc > (INT32_MAX - delta))) { return false; }
    if ((delta < 0) && (acc < (INT32_MIN - delta))) { return false; }
    *out = acc + delta;
    return true;
}

badExamples:
int32_t accumulate_torque(int32_t acc, int32_t delta)
{
    /* Overflows silently; undefined behavior, not a wrap. */
    return acc + delta;
}

goodExamples:
bool mean_sample(const uint32_t *sum, uint32_t count, uint32_t *out)
{
    if (count == 0U) { return false; }
    *out = *sum / count;
    return true;
}

badExamples:
uint32_t mean_sample(const uint32_t *sum, uint32_t count)
{
    /* count can be zero when the buffer was never filled. */
    return *sum / count;
}

goodExamples:
bool read_channel(const uint16_t *samples, size_t len, size_t idx, uint16_t *out)
{
    if (idx >= len) { return false; }
    *out = samples[idx];
    return true;
}

badExamples:
uint16_t read_channel(const uint16_t *samples, size_t idx)
{
    /* Caller-supplied idx is never compared against the array extent. */
    return samples[idx];
}

