goodExamples:
bool to_duty_cycle(int32_t raw, uint8_t *out)
{
    if ((raw < 0) || (raw > (int32_t)UINT8_MAX)) { return false; }
    *out = (uint8_t)raw;
    return true;
}

badExamples:
uint8_t to_duty_cycle(int32_t raw)
{
    /* Negative and >255 values wrap silently. */
    return raw;
}

