goodExamples:
#include <stdatomic.h>
#include <stdbool.h>

/* The shutdown ISR reaches this flag, so a lock-backed atomic would not do. */
#if ATOMIC_BOOL_LOCK_FREE != 2
#error "_Atomic bool is not always lock-free on this target"
#endif

static _Atomic bool shutdown_requested;

void request_shutdown(void)
{
    atomic_store_explicit(&shutdown_requested, true, memory_order_seq_cst);
}

badExamples:
static volatile bool shutdown_requested;

void request_shutdown(void)
{
    shutdown_requested = true; /* volatile is not atomic */
}

/* Atomic, so no data race - but nothing establishes the lock-free access
   the ISR needs; _Atomic alone permits a lock-backed implementation. */
static _Atomic bool fault_latched;

void isr_latch_fault(void)
{
    atomic_store_explicit(&fault_latched, true, memory_order_seq_cst);
}

